// seed: tests/seed.admin.spec.ts
// picking · кейс pick-14 (.qa/tests/picking/) — #7b8b97e9 (עבר QA 2026-10-12), правило владельца 11.10:
//   товар в двух местах X=4, Y=5 — в маршруте ОДНА станция, под ней оба места; один «לוקט» на товар;
//   списание — с места, где хватает всего (заказ 5 → Y 5→0, X 4); не хватает нигде — сначала с большего,
//   остаток со следующего (заказ 6 → 5 из Y + 1 из X), в יומן תנועות по записи «ליקוט» на место.
// ⚠️ НЕОБРАТИМО: создаёт 2 заказа buyer «test» (товар ₪0, заметка «QA-AUTO-7b8b-pick-…»), утверждает, комплектует,
//   доводит до «סופק» (отменить нельзя); 3 приёмки и 3 записи «ליקוט» в יומן תנועות — неудаляемы.
//   Как order-lifecycle / cart-checkout / picking-flow, идёт в обычном прогоне (пометки @data @orders — для --grep-invert).
// ⚠️ Корзина buyer общая на сервере → НЕ запускать параллельно с client-ordering/cart-checkout, orders/order-lifecycle,
//   inventory/inventory-lifecycle, picking/picking-flow.
// ליקוט — admin → «כניסה כעובד» → «עובד מחסן בדיקה», назад — «חזרה לחשבון הניהול».
// Места X/Y — свободные «ריק» полки, найденные на карте во время прогона. afterAll: заказы → «סופק», корзина buyer пуста,
// «הסרה מהמקום» в X/Y, товар удалён (архив), места «ריק».
import { test, expect, Page, Browser } from '@playwright/test';
import * as H from '../inventory/_places';
import { impersonate, backToAdmin } from '../warehouse-map/_helpers';

test.use({ storageState: H.ADMIN });
test.describe.configure({ mode: 'serial' });

const TS = Date.now().toString().slice(-7);
const WORKER = 'עובד מחסן בדיקה';
const P = `QA-AUTO-7b8b-pick-${TS}`;
const created = new Set<string>();
const used: H.Used = new Map();
const state: { id?: string; X?: H.Place; Y?: H.Place; orders: { no: string; url: string; id: string }[] } = { orders: [] };

// ---------- buyer: заказ ----------
async function emptyCart(page: Page) {
  await page.goto('/shop/cart');
  await expect(page.getByRole('heading', { name: 'העגלה שלי' })).toBeVisible({ timeout: 20_000 });
  const remove = page.getByRole('button', { name: /^הסרה מהעגלה/ });
  await expect(remove.first().or(page.getByText('העגלה ריקה'))).toBeVisible({ timeout: 20_000 });
  for (let n = await remove.count(); n > 0; n--) {
    await remove.first().click();
    await expect(remove).toHaveCount(n - 1, { timeout: 15_000 });
  }
  await expect(page.getByText('העגלה ריקה')).toBeVisible();
}

async function buyerPlaceOrder(browser: Browser, qty: number, note: string): Promise<string> {
  const ctx = await browser.newContext({ storageState: H.auth('buyer'), locale: 'he-IL', baseURL: test.info().project.use.baseURL });
  const page = await ctx.newPage();
  try {
    await emptyCart(page);
    await page.goto(`/shop/p/${state.id}`);
    let saved = page.waitForResponse((r) => r.url().includes('cart_set_item'));
    await page.getByRole('button', { name: /^הוסף לעגלה/ }).click();
    await saved;
    await page.goto('/shop/cart');
    await expect(page.getByText(P, { exact: true })).toBeVisible({ timeout: 20_000 });
    for (let i = 1; i < qty; i++) {
      saved = page.waitForResponse((r) => r.url().includes('cart_set_item'));
      await page.getByRole('button', { name: `הוספת יחידה — ${P}` }).click();
      await saved;
    }
    await page.getByRole('button', { name: 'המשך לביצוע הזמנה' }).click();
    await page.getByRole('textbox', { name: 'הערות להזמנה' }).fill(note);
    await page.getByRole('button', { name: 'שליחת הזמנה' }).click();
    await expect(page.getByRole('heading', { name: 'ההזמנה נקלטה!' })).toBeVisible({ timeout: 20_000 });
    return (await page.getByText(/^הזמנה\s*#\d+/).first().innerText()).match(/#(\d+)/)![1];
  } finally {
    await ctx.close();
  }
}

// ---------- admin: заказ ----------
const header = (page: Page) => page.getByRole('heading', { level: 1 }).locator('..');

async function openOrder(page: Page, no: string, url?: string) {
  if (url) await page.goto(url);
  else {
    await page.goto('/orders');
    await page.getByRole('combobox', { name: 'סינון לפי חודש' }).selectOption({ label: 'כל החודשים' });
    await page.getByRole('button', { name: new RegExp(`^#${no} `) }).click();
  }
  await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${no}` })).toBeVisible({ timeout: 20_000 });
}

/** Утвердить заказ; вернуть адрес и id. */
async function approve(page: Page, no: string) {
  await openOrder(page, no);
  await expect(page.getByText(P).first()).toBeVisible();
  await page.getByRole('button', { name: 'אישור הזמנה' }).click();
  const dlg = page.getByRole('dialog');
  await dlg.getByRole('textbox', { name: 'הערה (לא חובה)' }).fill(`QA-AUTO approve #7b8b97e9 ${TS}`);
  await dlg.getByRole('button', { name: 'אשר הזמנה' }).click();
  await expect(header(page)).toContainText('אושרה · ממתינה לליקוט', { timeout: 20_000 });
  const url = page.url();
  return { no, url, id: url.match(/orders\/([0-9a-f-]{36})/)![1] };
}

// ---------- ליקוט ----------
const itemsList = (page: Page) => page.getByRole('button', { name: /^פריטים לליקוט/ }).locator('xpath=following-sibling::*[1]');
const station = (page: Page) => page.getByRole('listitem').filter({ hasText: P });

/** Работник: маршрут заказа — одна станция с обоими местами; один «לוקט» → «סיום ליקוט». */
async function pickOrder(page: Page, o: { no: string; id: string }) {
  await impersonate(page, WORKER);
  await page.goto(`/warehouse/picking?order=${o.id}`);
  await expect(page.getByRole('heading', { level: 2, name: `הזמנה #${o.no}` })).toBeVisible({ timeout: 20_000 });
  await expect(page.getByText('תחנה אחת')).toBeVisible();
  await expect(page.getByRole('button', { name: 'פריטים לליקוט · 1' })).toBeVisible();
  await expect(itemsList(page)).toContainText(P);
  await expect(itemsList(page)).toContainText(state.X!.code);
  await expect(itemsList(page)).toContainText(state.Y!.code);

  await page.getByRole('button', { name: 'התחלת ליקוט', exact: true }).click();
  await expect(page.getByRole('heading', { level: 1, name: 'רשימת ליקוט' })).toBeVisible({ timeout: 20_000 });
  await expect(page.getByText('0/1', { exact: true })).toBeVisible();
  const st = station(page);
  await expect(st).toContainText(state.X!.code);
  await expect(st).toContainText(state.Y!.code);
  const picked = st.getByRole('button', { name: 'לוקט', exact: true });
  await expect(picked).toHaveCount(1); // один «לוקט» на товар, место не выбирается
  await picked.click();
  await expect(page.getByText('1/1', { exact: true })).toBeVisible({ timeout: 15_000 });
  await page.getByRole('button', { name: 'סיום ליקוט' }).click();
  await expect(page.getByText('הליקוט הושלם — ההזמנה סומנה «לוקטה»')).toBeVisible({ timeout: 20_000 });
  await backToAdmin(page);
}

async function placeQty(page: Page, place: H.Place) {
  await H.openPlace(page, place);
  return H.qtyInPlacePanel(page, P);
}

/** Записи «ליקוט» по товару для заказа #no: [{code, qty}] (место — по коду X/Y в тексте записи). */
async function pickJournal(page: Page, no: string) {
  await H.openMap(page);
  const expand = page.getByRole('button', { name: 'פתיחת יומן התנועות' });
  if (await expand.isVisible().catch(() => false)) await expand.click();
  await page.getByRole('textbox', { name: 'חיפוש ביומן התנועות' }).fill(P);
  return page
    .getByText('ליקוט', { exact: true }).and(page.locator(':not([role="tab"])'))
    .locator(`xpath=ancestor::div[.//*[contains(normalize-space(), "${P}")]][1]`)
    .filter({ hasText: `#${no}` });
}

async function expectJournalRow(entries: ReturnType<Page['locator']>, code: string, qty: number) {
  const e = entries.filter({ hasText: code });
  await expect(e).toHaveCount(1, { timeout: 20_000 });
  const lines = (await e.innerText()).split('\n').map((s) => s.trim()).filter(Boolean);
  expect(lines, `запись «ליקוט» ${code}: ${lines.join(' | ')}`).toContain(String(qty));
}

test.describe('picking — מוצר בשני מקומות: תחנה אחת, «לוקט» אחד, גריעה לפי כלל 11.10 (#7b8b97e9)', () => {
  test.afterAll(async ({ browser }) => {
    test.setTimeout(400_000);
    const ctx = await browser.newContext({ storageState: H.ADMIN, locale: 'he-IL', viewport: { width: 1440, height: 900 } });
    const page = await ctx.newPage();
    try {
      for (const o of state.orders) {
        await openOrder(page, o.no, o.url);
        const reject = page.getByRole('button', { name: 'דחייה' });
        if (await reject.count()) {
          await reject.click();
          const dlg = page.getByRole('dialog');
          await dlg.getByRole('textbox', { name: 'סיבת הדחייה *' }).fill('QA-AUTO cleanup #7b8b97e9');
          await dlg.getByRole('button', { name: 'דחה הזמנה' }).click();
          await expect(header(page)).toContainText('נדחתה', { timeout: 20_000 });
          continue;
        }
        for (const step of ['סמן כמוכנה למשלוח', 'סמן כיצאה למשלוח', 'סמן כסופקה']) {
          const btn = page.getByRole('button', { name: step });
          if ((await btn.count()) && (await btn.isEnabled())) {
            await btn.click();
            await expect(btn).toHaveCount(0, { timeout: 20_000 });
          }
        }
      }
    } finally {
      await ctx.close();
    }
    const bctx = await browser.newContext({ storageState: H.auth('buyer'), locale: 'he-IL', baseURL: test.info().project.use.baseURL });
    try {
      await emptyCart(await bctx.newPage());
    } finally {
      await bctx.close();
    }
    await H.cleanup(browser, created, used);
  });

  test('X=4, Y=5, הזמנה של 5: תחנה אחת עם שני המקומות, «לוקט» אחד → Y 5→0, X נשאר 4, ביומן רשומת «ליקוט» אחת מ-Y #7b8b97e9 @desktop @data @orders', async ({ page, browser }) => {
    test.setTimeout(600_000);
    const [X, Y] = await H.pickEmptyPlaces(page, 2, ['G', 'F', 'E']);
    state.X = X;
    state.Y = Y;
    await H.createProduct(page, P, `QA7B8BPK${TS}`, created, '0');
    H.track(used, P, X, Y);
    await H.bindPlace(page, P, X);
    await H.bindPlace(page, P, Y, true);
    await H.receive(page, P, 4, X.code);
    await H.receive(page, P, 5, Y.code);
    state.id = await H.productId(page, P);

    const no = await buyerPlaceOrder(browser, 5, `QA-AUTO-7b8b-pick-o5-${TS}`);
    const o = await approve(page, no);
    state.orders.push(o);
    await pickOrder(page, o);

    expect(await placeQty(page, Y), 'Y: всё количество взято отсюда').toBe(0);
    expect(await placeQty(page, X), 'X не тронут').toBe(4);
    await H.expectStock(page, P, 4);

    const entries = await pickJournal(page, no);
    await expect(entries).toHaveCount(1, { timeout: 20_000 });
    await expectJournalRow(entries, Y.code, 5);
  });

  test('X=4, Y=5, הזמנה של 6: תחנה אחת, «לוקט» אחד → 5 מ-Y ו-1 מ-X, ביומן שתי רשומות «ליקוט» #7b8b97e9 @desktop @data @orders', async ({ page, browser }) => {
    test.setTimeout(600_000);
    test.skip(!state.X || !state.Y || !state.id, 'товар не подготовлен');
    const { X, Y } = state as Required<typeof state>;
    await H.receive(page, P, 5, Y.code); // снова X=4, Y=5

    const no = await buyerPlaceOrder(browser, 6, `QA-AUTO-7b8b-pick-o6-${TS}`);
    const o = await approve(page, no);
    state.orders.push(o);
    await pickOrder(page, o);

    expect(await placeQty(page, Y), 'Y: сначала с большего — все 5').toBe(0);
    expect(await placeQty(page, X), 'X: остаток 1').toBe(3);
    await H.expectStock(page, P, 3);

    const entries = await pickJournal(page, no);
    await expect(entries).toHaveCount(2, { timeout: 20_000 });
    await expectJournalRow(entries, Y.code, 5);
    await expectJournalRow(entries, X.code, 1);
  });
});
